; ULTIMA.COM: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; INTRO: the title animation, sound and the chain load of BOOTUP.BIN (5CDD-6113).
;
; Overview: ULTIMA.COM is the intro. StartUp installs Ctrl-Break and critical-error
; handlers, checks for a CGA and sets mode 4 (SetGraphicsMode), seeds the library's random
; generator from the clock, copies BLANK.IBM (the frame, the ground, the party and the dragon)
; to the screen and loads EXOD.IBM into PictureBuf, NAME.DAT and ANIMATE.DAT. It then builds
; the title from pieces of EXOD.IBM: "Exodus" and "Ultima III" dissolve in with static
; (CopyPicture), "by", the "Lord British" signature is written point by point (DrawSignature),
; the copyright line; the party walks up to the dragon (AnimateParty), the dragon breathes fire
; with a roar of speaker noise and the party is gone (DrawDragonFire, DrawDragonAlone). A key
; press cuts each step short. Last it chain-loads BOOTUP.BIN over itself at 0100 with an
; "int 21h" planted at PSP:00FE (docs/HANDOFF.md). The picture pieces are given as scan lines
; of the 320 x 200 screen; RowTbl holds the screen offset of each line.
; Data: PictureBuf, NamePoints, AnimFrames, RowTbl, DiskCheckResult (UDATA).
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN StackArea:BYTE
EXTRN CursorCol:BYTE
EXTRN CursorRow:BYTE
EXTRN RandState:BYTE
EXTRN RandMonthDay:BYTE
EXTRN RandHourMin:BYTE
EXTRN RandSecHund:BYTE
EXTRN RandYear2:BYTE
EXTRN RandMonthDay2:BYTE
EXTRN RandHourMin2:BYTE
EXTRN RandSecHund2:BYTE
EXTRN DiskCheckStub:NEAR
EXTRN Random:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN LoadFile:NEAR
EXTRN PspInt20:BYTE
EXTRN PspFcb:BYTE
EXTRN FcbCurBlock:BYTE
EXTRN FcbRecSize:BYTE
EXTRN FcbFileSize:BYTE
EXTRN FcbCurRec:BYTE
EXTRN ChainInt21:BYTE
EXTRN Location:BYTE
EXTRN PictureBuf:BYTE
EXTRN VideoSeg:BYTE
EXTRN NamePoints:BYTE
EXTRN DiskCheckResult:BYTE
EXTRN AnimFrames:BYTE
EXTRN DissolveRand:BYTE
EXTRN FileBlankIbm:BYTE
EXTRN FileExodIbm:BYTE
EXTRN FileNameDat:BYTE
EXTRN FileAnimateDat:BYTE
EXTRN FileBootupBin:BYTE
EXTRN RowTbl:BYTE
EXTRN MsgNoGraphics:BYTE
PUBLIC StartUp
;------------------------------------------------------------------------------
; CritErrRetry: the int 24h (critical error) handler: AL = 1, retry the operation.
; BreakHandler: the int 23h (Ctrl-Break) handler: do nothing.
;------------------------------------------------------------------------------
CritErrRetry:	mov al, 1	;@5CDD
BreakHandler:	iret	;@5CDF
;------------------------------------------------------------------------------
; StartUp: the program's entry (jmp at 0100). Runs the whole intro, then
; chain-loads BOOTUP.BIN; never returns.
;------------------------------------------------------------------------------
StartUp:	cld	;@5CE0
	lea sp, StackArea	;@5CE1
	add sp, 100h	;@5CE5
	mov ax, 0	;@5CE9
	push es	;@5CEC
	mov es, ax	;@5CED
	mov ax, cs	;@5CEF
	mov word ptr es:[8Ch], offset BreakHandler	; vector 23h (0000:008C): Ctrl-Break	;@5CF1
	mov word ptr es:[8Eh], ax	;@5CF8
	mov word ptr es:[90h], offset CritErrRetry	; vector 24h (0000:0090): critical error	;@5CFC
	mov word ptr es:[92h], ax	;@5D03
	pop es	;@5D07
	mov al, 1	;@5D08
	mov dl, 0	;@5D0A
	mov ah, 33h	; DOS 33h AL=1 DL=0: Ctrl-Break checking off	;@5D0C
	int 21h	;@5D0E
	call SetGraphicsMode	;@5D10
; the library's Location (location) = 1: KeyReady does not animate tiles
	mov byte ptr Location, 1	;@5D13
; Seed the 16 bytes of RandState (K0103-K0112) from the clock and the date, twice over.
	mov ah, 2Ch	; DOS 2Ch get time: CH:CL hour:minute, DH:DL second:hundredths	;@5D18
	int 21h	;@5D1A
	mov word ptr RandSecHund2, dx	;@5D1C
	mov word ptr RandSecHund, dx	;@5D20
	mov word ptr RandHourMin2, cx	;@5D24
	mov word ptr RandHourMin, cx	;@5D28
	mov ah, 2Ah	; DOS 2Ah get date: CX year, DH:DL month:day	;@5D2C
	int 21h	;@5D2E
	mov word ptr RandMonthDay2, dx	;@5D30
	mov word ptr RandMonthDay, dx	;@5D34
	mov word ptr RandYear2, cx	;@5D38
	mov word ptr RandState, cx	;@5D3C
	lea bx, PictureBuf	;@5D40
	mov cx, 4000h	;@5D44
	lea dx, FileBlankIbm	;@5D47
	call LoadFile	;@5D4B
	push es	;@5D4E
	mov si, bx	;@5D4F
	mov di, 0	;@5D51
	mov es, word ptr VideoSeg	;@5D54
	shr cx, 1	;@5D58
	rep movsw	; BLANK.IBM straight to the screen	;@5D5A
	pop es	;@5D5C
; RowTbl: 100 pairs of words, 0000 2000 0050 2050 ...: the CGA offset of scan lines 0-199.
	lea di, RowTbl	;@5D5D
	mov cx, 64h	;@5D61
	mov ax, 0	;@5D64
StartUp_RowTbl:	stosw	;@5D67
	add ax, 2000h	; odd line: the second bank	;@5D68
	stosw	;@5D6B
	add ax, 0E050h	; back to the first bank, next line (-2000h + 50h)	;@5D6C
	loop StartUp_RowTbl	;@5D6F
	lea bx, PictureBuf	;@5D71
	mov cx, 4000h	;@5D75
	lea dx, FileExodIbm	;@5D78
	call LoadFile	;@5D7C
	lea bx, NamePoints	;@5D7F
	mov cx, 215h	;@5D83
	lea dx, FileNameDat	;@5D86
	call LoadFile	;@5D8A
	call DiskCheckStub	; the copy protection's stub: AL = 0 here	;@5D8D
	mov byte ptr DiskCheckResult, al	;@5D90
	lea bx, AnimFrames	;@5D93
	mov cx, 1700h	;@5D97
	lea dx, FileAnimateDat	;@5D9A
	call LoadFile	;@5D9E
	call DissolveExodus	;@5DA1
	mov ax, 2	;@5DA4
	call Delay	;@5DA7
	call DissolveUltima	;@5DAA
	mov ax, 5	;@5DAD
	call Delay	;@5DB0
	call DrawBy	;@5DB3
	mov ax, 3	;@5DB6
	call Delay	;@5DB9
	mov si, 9FFh	; delay between two points of the signature	;@5DBC
	call DrawSignature	;@5DBF
	mov ax, 2	;@5DC2
	call Delay	;@5DC5
	call DrawCopyright	;@5DC8
	mov ax, 6	;@5DCB
	call Delay	;@5DCE
; The copy protection: hang here for ever if the disk check said 0FFh (it never does: the stub
; returns 0).
StartUp_WaitDisk:	cmp byte ptr DiskCheckResult, 0FFh	;@5DD1
	je StartUp_WaitDisk	;@5DD6
	call AnimateParty	;@5DD8
	mov ax, 4	;@5DDB
	call Delay	;@5DDE
	call DrawDragonFire	;@5DE1
	call KeyReady	;@5DE4
	jne StartUp_FireOut	;@5DE7
; The roar of the fire: 400h toggles of the speaker bit at random intervals (speed-dependent).
	in al, 61h	; port 61h: speaker control	;@5DE9
	mov ah, al	;@5DEB
	and al, 0FCh	; bits 0-1 off: timer gate and speaker data	;@5DED
	mov dh, 0FFh	;@5DEF
	mov cx, 400h	;@5DF1
StartUp_Roar:	call Random	; DL = random below 0FFh	;@5DF4
StartUp_RoarDelay:	dec dl	;@5DF7
	jne StartUp_RoarDelay	;@5DF9
	out 61h, al	;@5DFB
	xor al, 2	; flip the speaker cone	;@5DFD
	loop StartUp_Roar	;@5DFF
	mov al, ah	;@5E01
	out 61h, al	; restore port 61h	;@5E03
StartUp_FireOut:	call DrawDragonAlone	;@5E05
	mov ax, 5	;@5E08
	call Delay	;@5E0B
StartUp_FlushKeys:	call KeyReady	;@5E0E
	je StartUp_ChainLoad	;@5E11
	call ReadKey	;@5E13
	jmp StartUp_FlushKeys	;@5E16
; The chain load (docs/HANDOFF.md): open BOOTUP.BIN with the PSP's FCB, make the record size
; the file size, plant "int 21h" (CD 21) at PSP:00FE and jump there with AH = 14h (sequential
; read): DOS reads the whole file to the DTA at 0100, over this program, and returns to 0100,
; BOOTUP's first instruction. The stack is put below 00FE, out of the way of the load.
StartUp_ChainLoad:	mov dx, 100h	;@5E18
	mov ah, 1Ah	; DOS 1Ah: DTA = 0100	;@5E1B
	int 21h	;@5E1D
	lea si, FileBootupBin	;@5E1F
	lea di, PspFcb	;@5E23
	mov al, 0	;@5E27
	mov ah, 29h	; DOS 29h: parse the file name into the FCB at PSP:005C	;@5E29
	int 21h	;@5E2B
	mov dx, di	;@5E2D
	mov ah, 0Fh	; DOS 0Fh: open the FCB	;@5E2F
	int 21h	;@5E31
	or al, al	;@5E33
	jne StartUp_Exit	; not found: quit to DOS	;@5E35
	mov ax, word ptr FcbFileSize	; file size ...	;@5E37
	mov word ptr FcbRecSize, ax	; ... as the record size	;@5E3A
	mov ax, 21CDh	; CD 21 = int 21h	;@5E3D
	mov word ptr ChainInt21, ax	;@5E40
	mov word ptr FcbCurBlock, 0	;@5E43
	mov byte ptr FcbCurRec, 0	;@5E49
	mov ah, 14h	; DOS 14h: sequential read, done by the planted int 21h	;@5E4E
	lea sp, ChainInt21	;@5E50
	jmp near ptr ChainInt21	;@5E54
StartUp_Exit:	jmp near ptr PspInt20	; PSP:0000 holds int 20h: terminate	;@5E57
;------------------------------------------------------------------------------
; Delay: wait AX x 65536 turns of a loop (speed-dependent), or not at all when a key is
; waiting. In: AX. Uses: AX, CX.
;------------------------------------------------------------------------------
Delay:	call KeyReady	;@5E5A
	jne Delay_Done	;@5E5D
	mov cx, 0	;@5E5F
Delay_Loop:	loop Delay_Loop	;@5E62
	dec ax	;@5E64
	jne Delay_Loop	;@5E65
Delay_Done:	ret	;@5E67
;------------------------------------------------------------------------------
; DrawSignature: write the "Lord British" signature under "Ultima III" from NAME.DAT
; (NamePoints): each (x, y) point is two white pixels at x+20 and x+21, row 192 - y, then a
; wait of SI loops. Stops at x = 0 or when a key is pressed. In: SI. Uses: BX, CX.
;------------------------------------------------------------------------------
DrawSignature:	push es	;@5E68
	mov es, word ptr VideoSeg	;@5E69
	lea bx, NamePoints	;@5E6D
	call KeyReady	;@5E71
	jne DrawSignature_Done	;@5E74
DrawSignature_Loop:	mov cl, byte ptr [bx]	; x	;@5E76
	test cl, 0FFh	;@5E78
	je DrawSignature_Done	; x = 0: the end	;@5E7B
	inc bx	;@5E7D
	mov ch, 0C0h	;@5E7E
	sub ch, byte ptr [bx]	; row = 192 - y	;@5E80
	inc bx	;@5E82
	call PlotPixel	;@5E83
	inc cl	;@5E86
	call PlotPixel	;@5E88
	mov cx, si	;@5E8B
DrawSignature_Wait:	loop DrawSignature_Wait	;@5E8D
	call KeyReady	;@5E8F
	je DrawSignature_Loop	;@5E92
DrawSignature_Done:	pop es	;@5E94
	ret	;@5E95
;------------------------------------------------------------------------------
; DissolveExodus: "Exodus" (picture lines 8-84, bytes 7-72) appears on the screen in 64
; passes of CopyPicture with a rising threshold (AL = 0, 4, ... 0FCh), each showing more of
; it with static from the speaker; then a plain copy. A key skips to the plain copy.
;------------------------------------------------------------------------------
DissolveExodus:	mov al, 0	;@5E96
DissolveExodus_Loop:	call KeyReady	;@5E98
	jne DissolveExodus_Full	;@5E9B
	mov ah, 0FFh	; dissolve	;@5E9D
	mov cx, 7	; from byte 7 of the line (pixel 28)	;@5E9F
	mov bl, 8	; picture line 8 ...	;@5EA2
	mov bh, 8	; ... to screen line 8	;@5EA4
	mov dl, 4Dh	; 77 lines	;@5EA6
	mov dh, 21h	; 33 words (264 pixels) wide	;@5EA8
	call CopyPicture	;@5EAA
	add al, 4	;@5EAD
	jne DissolveExodus_Loop	;@5EAF
DissolveExodus_Full:	mov ah, 0	;@5EB1
	mov cx, 7	;@5EB3
	mov bl, 8	;@5EB6
	mov bh, 8	;@5EB8
	mov dl, 4Dh	;@5EBA
	mov dh, 21h	;@5EBC
	call CopyPicture	;@5EBE
	ret	;@5EC1
;------------------------------------------------------------------------------
; DrawDragonFire: the dragon's breath: EXOD.IBM lines 168-183, bytes 29-50 (pixels 116-203,
; a cloud of fire over the party and the front of the dragon) copied to the same place.
; Skipped when a key is waiting.
;------------------------------------------------------------------------------
DrawDragonFire:	call KeyReady	;@5EC2
	jne DrawDragonFire_Done	;@5EC5
	mov ah, 0	;@5EC7
	mov cx, 1Dh	;@5EC9
	mov bl, 0A8h	;@5ECC
	mov bh, 0A8h	;@5ECE
	mov dl, 10h	;@5ED0
	mov dh, 0Bh	;@5ED2
	call CopyPicture	;@5ED4
DrawDragonFire_Done:	ret	;@5ED7
;------------------------------------------------------------------------------
; DrawDragonAlone: EXOD.IBM lines 152-167 (empty ground and a dragon that does not breathe),
; bytes 29-52, copied to screen lines 168-183: the fire is out and the party is gone.
; Skipped when a key is waiting.
;------------------------------------------------------------------------------
DrawDragonAlone:	call KeyReady	;@5ED8
	jne DrawDragonAlone_Done	;@5EDB
	mov ah, 0	;@5EDD
	mov cx, 1Dh	;@5EDF
	mov bl, 98h	; from picture line 152 ...	;@5EE2
	mov bh, 0A8h	; ... to screen line 168	;@5EE4
	mov dl, 10h	;@5EE6
	mov dh, 0Ch	;@5EE8
	call CopyPicture	;@5EEA
DrawDragonAlone_Done:	ret	;@5EED
;------------------------------------------------------------------------------
; DissolveUltima: as DissolveExodus for "Ultima III" (lines 85-127, bytes 7-72).
;------------------------------------------------------------------------------
DissolveUltima:	mov al, 0	;@5EEE
DissolveUltima_Loop:	call KeyReady	;@5EF0
	jne DissolveUltima_Full	;@5EF3
	mov ah, 0FFh	;@5EF5
	mov cx, 7	;@5EF7
	mov bl, 55h	;@5EFA
	mov bh, 55h	;@5EFC
	mov dl, 2Bh	;@5EFE
	mov dh, 21h	;@5F00
	call CopyPicture	;@5F02
	add al, 4	;@5F05
	jne DissolveUltima_Loop	;@5F07
DissolveUltima_Full:	mov ah, 0	;@5F09
	mov cx, 7	;@5F0B
	mov bl, 55h	;@5F0E
	mov bh, 55h	;@5F10
	mov dl, 2Bh	;@5F12
	mov dh, 21h	;@5F14
	call CopyPicture	;@5F16
	ret	;@5F19
;------------------------------------------------------------------------------
; DrawBy: "by" (lines 132-140, bytes 17-24) copied to the screen, unless a key is waiting.
;------------------------------------------------------------------------------
DrawBy:	call KeyReady	;@5F1A
	jne DrawBy_Done	;@5F1D
	mov ah, 0	;@5F1F
	mov cx, 11h	;@5F21
	mov bl, 84h	;@5F24
	mov bh, 84h	;@5F26
	mov dl, 9	;@5F28
	mov dh, 4	;@5F2A
	call CopyPicture	;@5F2C
DrawBy_Done:	ret	;@5F2F
;------------------------------------------------------------------------------
; DrawCopyright: "COPYRIGHT (C) 1983 ORIGIN SYSTEMS" (lines 146-150, bytes 5-68) copied to
; the screen (always, even with a key waiting).
;------------------------------------------------------------------------------
DrawCopyright:	mov ah, 0	;@5F30
	mov cx, 5	;@5F32
	mov bl, 92h	;@5F35
	mov bh, 92h	;@5F37
	mov dl, 5	;@5F39
	mov dh, 20h	;@5F3B
	call CopyPicture	;@5F3D
	ret	;@5F40
;------------------------------------------------------------------------------
; PlotPixel: set the pixel at x = CL + 20, scan line CH to colour 3 (white) on the screen
; (ES = the video segment). In: CL, CH, ES. Uses: nothing.
;------------------------------------------------------------------------------
PlotPixel:	push ax	;@5F41
	push bx	;@5F42
	push cx	;@5F43
	add cl, 14h	;@5F44
	mov al, cl	;@5F47
	shr al, 1	;@5F49
	shr al, 1	; AL = byte of the line (4 pixels a byte)	;@5F4B
	mov ah, 0C0h	; both bits of the leftmost pixel, shifted to the pixel	;@5F4D
	and cl, 3	;@5F4F
	shl cl, 1	;@5F52
	shr ah, cl	;@5F54
	mov bl, ch	;@5F56
	mov bh, 0	;@5F58
	shl bx, 1	;@5F5A
	mov bx, word ptr RowTbl[bx]	;@5F5C
	add bl, al	;@5F60
	adc bh, 0	;@5F62
	or byte ptr es:[bx], ah	;@5F65
	pop cx	;@5F68
	pop bx	;@5F69
	pop ax	;@5F6A
	ret	;@5F6B
;------------------------------------------------------------------------------
; CopyPicture: copy a rectangle of EXOD.IBM (PictureBuf, in the screen's own layout) to the
; screen. In: BL = first picture line, BH = first screen line, DL = number of lines, DH =
; width in words, CX = first byte of each line (column / 4), AH = 0 plain copy, else
; dissolve: each word is copied only when a pseudo-random byte (DissolveRand) is at most
; AL AND 0F8h, with a click of the speaker, otherwise the screen word is cleared to black.
; Uses: nothing (saves all).
;------------------------------------------------------------------------------
CopyPicture:	pushf	;@5F6C
	push ax	;@5F6D
	push bx	;@5F6E
	push cx	; [bp+0Eh]: first byte of each line	;@5F6F
	push dx	;@5F70
	push bp	;@5F71
	push si	;@5F72
	push di	;@5F73
	push es	;@5F74
	push bx	; [bp+2]: picture line, screen line	;@5F75
	and al, 0F8h	;@5F76
	push ax	; [bp]: threshold, [bp+1]: dissolve flag	;@5F78
	mov bp, sp	;@5F79
	mov es, word ptr VideoSeg	;@5F7B
	mov ch, 0	;@5F7F
CopyPicture_Line:	mov ax, word ptr [bp+2]	;@5F81
	mov bl, al	;@5F84
	mov bh, 0	;@5F86
	shl bx, 1	;@5F88
	mov si, word ptr RowTbl[bx]	;@5F8A
	add si, offset PictureBuf	;@5F8E
	add si, word ptr [bp+0Eh]	;@5F92
	mov bl, ah	;@5F95
	mov bh, 0	;@5F97
	shl bx, 1	;@5F99
	mov di, word ptr RowTbl[bx]	;@5F9B
	add di, word ptr [bp+0Eh]	;@5F9F
	mov cl, dh	;@5FA2
CopyPicture_Word:	cmp byte ptr [bp+1], 0	;@5FA4
	je CopyPicture_Copy	;@5FA8
	mov ax, word ptr DissolveRand	; next pseudo-random byte: AL' = AL + 1Dh + AH' = AL + 1Dh	;@5FAA
	add al, 1Dh	;@5FAD
	mov bl, al	;@5FAF
	add al, ah	;@5FB1
	mov ah, bl	;@5FB3
	mov word ptr DissolveRand, ax	;@5FB5
	cmp al, byte ptr [bp]	;@5FB8
	jbe CopyPicture_Click	;@5FBB
	mov ax, 0	; not yet: black	;@5FBD
	add si, 2	;@5FC0
	jmp short CopyPicture_Store	;@5FC3
CopyPicture_Click:	in al, 61h	;@5FC5
	xor al, 2	; flip the speaker bit (timer gate off): a click	;@5FC7
	and al, 0FEh	;@5FC9
	out 61h, al	;@5FCB
CopyPicture_Copy:	lodsw	;@5FCD
CopyPicture_Store:	stosw	;@5FCE
	loop CopyPicture_Word	;@5FCF
	add word ptr [bp+2], 101h	; next picture line and screen line	;@5FD1
	dec dl	;@5FD6
	jne CopyPicture_Line	;@5FD8
	add sp, 4	;@5FDA
	pop es	;@5FDD
	pop di	;@5FDE
	pop si	;@5FDF
	pop bp	;@5FE0
	pop dx	;@5FE1
	pop cx	;@5FE2
	pop bx	;@5FE3
	pop ax	;@5FE4
	popf	;@5FE5
	ret	;@5FE6
; The three phases of AnimateParty, indexed 2, 1, 0 (in that order): the party walks right
; (pictures 0-3 at each x 42 to 49), back left (pictures 3-0, x 49 to 43), then right
; again up to the dragon (x 43 to 52).
AnimStepTbl label byte
	db 1h,0FFh,1h	;@5FE7
AnimEndPicTbl label byte
	db 4h,0FFh,4h	;@5FEA
AnimEndXTbl label byte
	db 34h,2Bh,31h	;@5FED
AnimStartPicTbl label byte
	db 0h,3h,0h	;@5FF0
;------------------------------------------------------------------------------
; AnimateParty: the party (ANIMATE.DAT) walks up to the dragon on the ground line, four
; pictures for each step of 2 pixels, a fixed delay (speed-dependent) between pictures;
; stops when a key is pressed. Uses: AX, BX, CX, SI.
;------------------------------------------------------------------------------
AnimateParty:	mov si, 2	;@5FF3
	mov bx, 2Ah	; x = 42 (pixel 104)	;@5FF6
	mov ah, 0	;@5FF9
AnimateParty_Step:	call KeyReady	;@5FFB
	jne AnimateParty_Done	;@5FFE
	mov al, byte ptr AnimStartPicTbl[si]	;@6000
AnimateParty_Frame:	call DrawAnimFrame	;@6004
	mov cx, 9000h	;@6007
AnimateParty_Wait:	loop AnimateParty_Wait	;@600A
	add al, byte ptr AnimStepTbl[si]	;@600C
	cmp al, byte ptr AnimEndPicTbl[si]	;@6010
	jne AnimateParty_Frame	;@6014
	add bl, byte ptr AnimStepTbl[si]	;@6016
	cmp bl, byte ptr AnimEndXTbl[si]	;@601A
	jne AnimateParty_Step	;@601E
	dec si	;@6020
	jns AnimateParty_Step	;@6021
AnimateParty_Done:	ret	;@6023
;------------------------------------------------------------------------------
; DrawAnimFrame: draw ANIMATE.DAT picture AL (0-3) at x position BX, i.e. pixel 2*BX+20, on
; screen lines 168-183: 16 rows of 23 bytes from AnimFrames + AL*5C0h + shift*170h, the
; shift being the pixel's position in its byte, with a cleared byte on each side to wipe
; the previous position. As the pixel is always even, only shifts 0 and 2 are used.
; In: AL, BX. Uses: nothing (saves all).
;------------------------------------------------------------------------------
DrawAnimFrame:	pushf	;@6024
	push ax	;@6025
	push bx	;@6026
	push cx	;@6027
	push dx	;@6028
	push si	;@6029
	push di	;@602A
	push es	;@602B
	mov es, word ptr VideoSeg	;@602C
	shl bx, 1	;@6030
	add bx, 14h	; BX = pixel column	;@6032
	mov cx, 5C0h	; 1472 bytes a picture (4 shifts)	;@6035
	mul cx	;@6038
	mov di, ax	;@603A
	mov ax, 170h	; 368 bytes a shift (16 x 23)	;@603C
	mov dx, bx	;@603F
	and dx, 3	;@6041
	mul dx	;@6045
	add ax, di	;@6047
	shr bx, 1	;@6049
	shr bx, 1	;@604B
	mov dx, bx	;@604D
	mov si, ax	;@604F
	lea si, AnimFrames[si]	;@6051
	mov bx, 150h	; RowTbl entry of line 168	;@6055
	mov ax, 10h	; 16 rows	;@6058
DrawAnimFrame_Row:	mov di, word ptr RowTbl[bx]	;@605B
	add bx, 2	;@605F
	add di, dx	;@6062
	mov byte ptr es:[di-1], 0	;@6064
	mov cx, 17h	;@6069
	rep movsb	;@606C
	mov byte ptr es:[di], 0	;@606E
	dec ax	;@6072
	jne DrawAnimFrame_Row	;@6073
	pop es	;@6075
	pop di	;@6076
	pop si	;@6077
	pop dx	;@6078
	pop cx	;@6079
	pop bx	;@607A
	pop ax	;@607B
	popf	;@607C
	ret	;@607D
;------------------------------------------------------------------------------
; SetGraphicsMode: make sure there is a CGA and switch it to 320 x 200 in 4 colours (mode 4,
; black background, palette 1: cyan, magenta, white); cursor to 0,0. When the monochrome
; adapter is active (mode 7), test that video memory answers at B800 and that the BIOS's
; equipment word agrees with int 11h, then mark the colour card as the initial display.
; On failure print "Unable to access graphics display." and hang for ever.
; Uses: CX (not saved).
;------------------------------------------------------------------------------
SetGraphicsMode:	pushf	;@607E
	push ax	;@607F
	push bx	;@6080
	push dx	;@6081
	push bp	;@6082
	mov ah, 0Fh	; BIOS 10h/0Fh: current video mode in AL	;@6083
	int 10h	;@6085
	mov cx, ax	;@6087
	cmp al, 7	; monochrome text?	;@6089
	jne SetGraphicsMode_Set	;@608B
	int 11h	; BIOS equipment list in AX	;@608D
	mov cx, ax	;@608F
	push es	;@6091
	mov es, word ptr VideoSeg	;@6092
	mov bx, 0	;@6096
	mov dx, word ptr es:[bx]	; write and read back three patterns at B800:0000	;@6099
	mov word ptr es:[bx], 5555h	;@609C
	cmp word ptr es:[bx], 5555h	;@60A1
	jne SetGraphicsMode_Fail	;@60A6
	mov word ptr es:[bx], 0AAAAh	;@60A8
	cmp word ptr es:[bx], 0AAAAh	;@60AD
	jne SetGraphicsMode_Fail	;@60B2
	mov word ptr es:[bx], 0D221h	;@60B4
	cmp word ptr es:[bx], 0D221h	;@60B9
	jne SetGraphicsMode_Fail	;@60BE
	mov word ptr es:[bx], dx	;@60C0
	mov ax, 0	;@60C3
	mov es, ax	;@60C6
	mov bx, 410h	; 0040:0010, the BIOS equipment word	;@60C8
	mov ax, word ptr es:[bx]	;@60CB
	cmp ax, cx	;@60CE
	jne SetGraphicsMode_Fail	; (leaves ES on the stack: it hangs anyway)	;@60D0
	and ax, 0FFEFh	; initial video mode bits 5-4: 11 (mono) -> 10 (80 x 25 colour)	;@60D2
	mov word ptr es:[bx], ax	;@60D5
	pop es	;@60D8
SetGraphicsMode_Set:	mov ah, 0	;@60D9
	mov al, 4	; BIOS 10h/00h: mode 4, 320 x 200 x 4 colours	;@60DB
	int 10h	;@60DD
	mov ah, 0Bh	; BIOS 10h/0Bh BH=0: background colour 0, black	;@60DF
	mov bh, 0	;@60E1
	mov bl, 0	;@60E3
	int 10h	;@60E5
	mov ah, 0Bh	; BIOS 10h/0Bh BH=1: palette 1	;@60E7
	mov bh, 1	;@60E9
	mov bl, 1	;@60EB
	int 10h	;@60ED
	mov byte ptr CursorRow, 0	;@60EF
	mov byte ptr CursorCol, 0	;@60F4
	pop bp	;@60F9
	pop dx	;@60FA
	pop bx	;@60FB
	pop ax	;@60FC
	popf	;@60FD
	ret	;@60FE
SetGraphicsMode_Fail:	lea si, MsgNoGraphics	;@60FF
	mov bl, 7	;@6103
	cld	;@6105
SetGraphicsMode_Print:	lodsb	;@6106
	cmp al, 0	;@6107
	je SetGraphicsMode_Hang	;@6109
	mov ah, 0Eh	; BIOS 10h/0Eh: teletype output	;@610B
	int 10h	;@610D
	jmp SetGraphicsMode_Print	;@610F
SetGraphicsMode_Hang:	jmp SetGraphicsMode_Hang	;@6111
CODE ENDS
END
